const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const newMexico = ee.FeatureCollection("TIGER/2018/States").filter(ee.Filter.eq('NAME', 'New Mexico')).geometry();
  const yearTarget = 2016;
  const periodStartYear = 1986; // "past 30 years" relative to 2016
  const periodEndYear = 2015;
  const month = 7; // July

  // Use a climate reanalysis dataset suitable for long-term monthly analysis.
  // ERA5-Land provides monthly skin temperature from 1981 onwards.
  const collection = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY_AGGR')
                      .select('skin_temperature')
                      .filter(ee.Filter.calendarRange(month, month, 'month'));

  const convertKtoC = function(image) {
    const tempC = image.subtract(273.15).rename('LST_C');
    return tempC.copyProperties(image, ['system:time_start']);
  };

  // 2. Data Acquisition
  const targetImageJuly2016 = collection
                                .filter(ee.Filter.calendarRange(yearTarget, yearTarget, 'year'))
                                .map(convertKtoC)
                                .first();

  const otherYearsJuly = collection
                            .filter(ee.Filter.calendarRange(periodStartYear, periodEndYear, 'year'))
                            .map(convertKtoC);

  // 3. Validation Checks for Data Availability
  const targetImageCount = ee.ImageCollection([targetImageJuly2016]).size().getInfo();
  const otherYearsCount = otherYearsJuly.size().getInfo();

  if (targetImageCount === 0 || otherYearsCount === 0) {
    console.log(`Image count for July ${yearTarget}: ${targetImageCount}`);
    console.log(`Image count for Julys ${periodStartYear}-${periodEndYear}: ${otherYearsCount}`);
    console.log("Empty Collection: No images found for one or both periods.");
    console.log('C1');
    return;
  }
  console.log(`Image found for July ${yearTarget}.`);
  console.log(`${otherYearsCount} images found for Julys ${periodStartYear}-${periodEndYear}.`);

  // 4. Processing & Calculation
  const scale = 9000; // Native resolution of ERA5-Land is ~9km

  const temp2016 = targetImageJuly2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newMexico,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_C');

  // Create a max composite of all other years to find the single highest temperature
  const maxTempOtherYearsImage = otherYearsJuly.max();
  const maxTempOtherYears = maxTempOtherYearsImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newMexico,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_C');

  const lst2016 = temp2016.getInfo();
  const maxLstOtherYears = maxTempOtherYears.getInfo();

  // 5. Validation & Final Answer
  if (lst2016 === null || maxLstOtherYears === null) {
      console.log(`2016 LST: ${lst2016}`);
      console.log(`Max LST in other years: ${maxLstOtherYears}`);
      console.log("Calculation resulted in null.");
      console.log('C3');
      return;
  }

  console.log(`Mean LST for July 2016: ${lst2016.toFixed(2)} C`);
  console.log(`Highest mean LST for any other July (${periodStartYear}-${periodEndYear}): ${maxLstOtherYears.toFixed(2)} C`);

  if (lst2016 > maxLstOtherYears) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
